const { useState } = React;

const IMAGE = "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/wallhaven-4lol1r_920d1162-f760-456a-8dc0-a03f62dfbfe2.webp";
const BOXES = ["border", "padding", "content"].map(name => `${name}-box`);
const REGIONS = [
  { label: "border", rank: 0 },
  { label: "padding", rank: 1 },
  { label: "content", rank: 2 },
];
// 三个盒子边界的位置：border 8px，padding 24px
const OUTLINES = ["inset-0", "inset-[8px]", "inset-[32px]"];

// 盒模型标线画在卡片外层，不受 mask 裁剪
const Card = ({ property, clip, showBox }) => {
  const style =
    property === "background-clip"
      ? { backgroundImage: `url("${IMAGE}")`, backgroundClip: clip }
      : {
          backgroundImage: `url("${IMAGE}")`,
          maskImage: "linear-gradient(#000 0 0)",
          WebkitMaskImage: "linear-gradient(#000 0 0)",
          maskClip: clip,
          WebkitMaskClip: clip,
        };
  return (
    <div className="flex min-w-0 flex-col items-center gap-2">
      <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">
        {property}: {clip}
      </code>
      <div className="relative aspect-square w-full max-w-[220px]">
        <div className="absolute inset-0 rounded-tau-md border-8 border-accent/50 bg-cover bg-center p-6" style={style} />
        {showBox &&
          OUTLINES.map((inset, index) => (
            <div
              key={inset}
              className={`pointer-events-none absolute border border-dashed ${inset} ${BOXES[index] === clip ? "border-accent" : "border-line-1"}`}
            />
          ))}
      </div>
    </div>
  );
};

const Status = ({ visible, children }) => <ui.Tag color={visible ? "green" : "gray"}>{children}</ui.Tag>;

const Component = () => {
  const [clip, setClip] = useState("padding-box");
  const [showBox, setShowBox] = useState(true);
  const clipRank = BOXES.indexOf(clip);

  return (
    <div className="@container flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-2">
        {BOXES.map(box => (
          <button
            key={box}
            type="button"
            aria-pressed={clip === box}
            onClick={() => setClip(box)}
            className={`cursor-pointer rounded-full border px-3 py-1 font-tau-mono text-tau-sm transition-colors ${
              clip === box ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {box}
          </button>
        ))}
        <div className="ml-auto">
          <ui.Switch checked={showBox} onCheckedChange={setShowBox} label="显示盒模型边界" size="sm" />
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4 rounded-tau-md border border-line-1 p-4">
        <Card property="background-clip" clip={clip} showBox={showBox} />
        <Card property="mask-clip" clip={clip} showBox={showBox} />
      </div>
      <div className="grid grid-cols-[auto_minmax(0,1fr)_minmax(0,1fr)] items-center gap-x-4 gap-y-1.5 rounded-tau-md border border-line-1 px-3 py-2.5">
        <span className="text-tau-sm text-ink-3">区域</span>
        <span className="font-tau-mono text-tau-sm text-ink-3">background-clip</span>
        <span className="font-tau-mono text-tau-sm text-ink-3">mask-clip</span>
        {REGIONS.map(region => {
          const inside = region.rank >= clipRank;
          return (
            <React.Fragment key={region.label}>
              <span className="font-tau-mono text-tau-sm text-ink-2">{region.label}</span>
              <span>
                <Status visible={inside}>{inside ? "画背景" : region.rank === 0 ? "只剩边框" : "空白"}</Status>
              </span>
              <span>
                <Status visible={inside}>{inside ? "可见" : "完全透明"}</Status>
              </span>
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
};

const { useState } = React;

const ITEMS = Array.from({ length: 20 }, (_, index) => index + 1);
const MODES = [
  { value: "none", label: "无 mask" },
  { value: "fixed", label: "固定渐隐" },
  { value: "scroll", label: "跟随滚动" },
];

// 上下各 fade% 渐变到完全透明；遮罩只看 alpha，所以用黑色即可
const gradient = (top, bottom) =>
  `linear-gradient(180deg, transparent 0%, #000 ${top}%, #000 ${100 - bottom}%, transparent 100%)`;

const Component = () => {
  const [mode, setMode] = useState("fixed");
  const [fade, setFade] = useState(12);
  const [edges, setEdges] = useState({ top: 0, bottom: 1 });

  // 跟随滚动：离顶部、底部越近，对应一侧的渐隐越弱，到边界时完全不渐隐
  const handleScroll = event => {
    const { scrollTop, scrollHeight, clientHeight } = event.currentTarget;
    const rest = scrollHeight - clientHeight - scrollTop;
    setEdges({ top: Math.min(scrollTop / 40, 1), bottom: Math.min(rest / 40, 1) });
  };

  const topFade = mode === "scroll" ? Math.round(fade * edges.top) : fade;
  const bottomFade = mode === "scroll" ? Math.round(fade * edges.bottom) : fade;
  const mask = mode === "none" ? "none" : gradient(topFade, bottomFade);
  const maskStyle = { mask, WebkitMask: mask };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
        }
      `}</style>
      <div className="flex flex-wrap items-center gap-2">
        {MODES.map(item => (
          <button
            key={item.value}
            type="button"
            aria-pressed={mode === item.value}
            onClick={() => setMode(item.value)}
            className={`cursor-pointer rounded-full border px-3 py-1 text-tau-sm transition-colors ${
              mode === item.value ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
            }`}
          >
            {item.label}
          </button>
        ))}
        <label className="ml-auto flex min-w-[200px] items-center gap-3">
          <span className="shrink-0 text-tau-sm text-ink-2">渐隐范围</span>
          <input
            type="range"
            min={4}
            max={30}
            value={fade}
            disabled={mode === "none"}
            onChange={event => setFade(Number(event.target.value))}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer disabled:cursor-not-allowed disabled:opacity-50"
          />
          <span className="w-10 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{fade}%</span>
        </label>
      </div>
      <div className="grid grid-cols-[minmax(0,1fr)_auto] gap-3">
        <div className="h-[240px] overflow-y-auto rounded-tau-md border border-line-1" style={maskStyle} onScroll={handleScroll}>
          {ITEMS.map(index => (
            <div key={index} className="flex items-center gap-3 border-b border-line-2 px-3 py-2 last:border-b-0">
              <span className="grid size-6 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-tiny text-ink-2">{index}</span>
              <span className="text-tau-body text-ink-1">第 {index} 项内容</span>
              <span className="ml-auto h-2 w-16 rounded-full bg-track" />
            </div>
          ))}
        </div>
        <div className="flex flex-col items-center gap-1.5">
          <div className="w-8 flex-1 rounded-tau-sm border border-line-1">
            <div className="size-full rounded-tau-sm bg-accent" style={maskStyle} />
          </div>
          <span className="text-tau-tiny text-ink-3">遮罩</span>
        </div>
      </div>
      <code className="min-w-0 break-all rounded-tau-sm bg-hover px-2 py-1.5 font-tau-mono text-tau-sm text-ink-2">mask: {mask};</code>
    </div>
  );
};
